INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich als IT-Mitarbeiter automatisch Verträge unterschreiben darf?', 2, '[{"text": "Nein", "correct": true, "because": "Brauche ausdrückliche Befugnis"}, {"text": "Ja", "correct": false, "because": "Ohne Vollmacht nicht erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich im Namen der Firma Software kaufe?', 3, '[{"text": "Schriftliche Bevollmächtigung", "correct": true, "because": "Legitimiert meine Entscheidung"}, {"text": "Mündliche Zustimmung", "correct": false, "because": "Rechtlich unsicher"}, {"text": "Eigene Initiative", "correct": false, "because": "Nicht ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben darf ich mit einer Befugnis im IT-Bereich übernehmen?', 5, '[{"text": "Hardware-Beschaffung", "correct": true, "because": "Falls bevollmächtigt"}, {"text": "Vertragsabschlüsse", "correct": true, "because": "Mit entsprechender Vollmacht"}, {"text": "Firmenstrategie ändern", "correct": false, "because": "Übersteigt IT-Befugnis"}, {"text": "Personalentscheidungen", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Vollmacht muss schriftlich sein. b) Sie erlaubt alles im IT-Bereich.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Formfrei möglich, Umfang begrenzt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich im IT-Team Entscheidungen treffe?', 4, '[{"text": "Grenzen meiner Befugnis", "correct": false, "because": "Definiert meinen Spielraum"}, {"text": "Firmenrichtlinien", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich mit einer Vollmacht alles im IT-Bereich entscheiden darf. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Begrenzt auf definierte Aufgaben"}, {"text": "Ja", "correct": false, "because": "Umfang ist eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme wähle ich, um sicher eine Hardware-Bestellung zu tätigen?', 3, '[{"text": "Vollmacht vom Chef einholen", "correct": true, "because": "Legitimiert meine Handlung"}, {"text": "Selbst entscheiden", "correct": false, "because": "Risiko ohne Befugnis"}, {"text": "Team abstimmen", "correct": false, "because": "Nicht rechtlich bindend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei einer Befugnis für IT-Aufgaben wichtig?', 5, '[{"text": "Klar definierter Umfang", "correct": true, "because": "Verhindert Missverständnisse"}, {"text": "Dokumentation", "correct": true, "because": "Nachweis der Befugnis"}, {"text": "Persönliche Präferenz", "correct": false, "because": "Kein rechtlicher Faktor"}, {"text": "Büroausstattung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) eine Vollmacht jederzeit widerrufen werden kann und b) sie automatisch erlischt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Widerruf möglich, Erlöschen nicht automatisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um im Namen der Firma ein IT-System zu bestellen?', 4, '[{"text": "Bevollmächtigung", "correct": false, "because": "Legitimiert die Bestellung"}, {"text": "Vertragsdetails", "correct": false, "because": "Definieren Umfang"}, {"text": "Persönliche Meinung", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Darf ich ohne Vollmacht einen Liefervertrag abschließen?', 2, '[{"text": "Nein", "correct": true, "because": "Fehlt rechtliche Grundlage"}, {"text": "Ja", "correct": false, "because": "Nur mit Befugnis erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine klare Befugnis im IT-Bereich?', 4, '[{"text": "Rechtssicherheit", "correct": true, "because": "Schützt vor Haftung"}, {"text": "Effiziente Entscheidungen", "correct": true, "because": "Klärt Verantwortung"}, {"text": "Höhere Gehälter", "correct": false, "because": "Kein direkter Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Vollmacht nur für Führungskräfte gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann jedem erteilt werden"}, {"text": "Ja", "correct": false, "because": "Nicht positionsgebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Befugnis für IT-Beschaffung?', 3, '[{"text": "Verantwortung delegieren", "correct": true, "because": "Ermöglicht Vertretung"}, {"text": "Kosten erhöhen", "correct": false, "because": "Kein Ziel"}, {"text": "Zeit sparen", "correct": false, "because": "Indirekter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Vollmacht kann mündlich erteilt werden. b) Sie erlaubt nur Käufe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Umfang nicht auf Käufe begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt eine Vollmacht bei einem IT-Projekt?', 4, '[{"text": "Befugt zur Vertretung", "correct": true, "because": "Ermöglicht Entscheidungen"}, {"text": "Ersetzt Fachwissen", "correct": false, "because": "Nur rechtlicher Aspekt"}, {"text": "Verkürzt Projekte", "correct": false, "because": "Indirekter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Vollmacht automatisch alle IT-Aufgaben abdeckt?', 2, '[{"text": "Nein", "correct": true, "because": "Umfang muss spezifiziert sein"}, {"text": "Ja", "correct": false, "because": "Nicht unbegrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Befugnis im IT-Bereich effektiv?', 5, '[{"text": "Klarer Aufgabenbereich", "correct": true, "because": "Verhindert Überschreitungen"}, {"text": "Schriftliche Fixierung", "correct": true, "because": "Sichert Nachweis"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Kriterium"}, {"text": "Persönliche Vorlieben", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Darf ich mit einer Vollmacht die Firma verkaufen?', 3, '[{"text": "Nein", "correct": true, "because": "Übersteigt übliche IT-Befugnis"}, {"text": "Ja", "correct": false, "because": "Nur mit spezieller Vollmacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario zeigt eine typische IT-Befugnis?', 4, '[{"text": "Bestellung von Software", "correct": true, "because": "Falls bevollmächtigt"}, {"text": "Änderung der Unternehmensstruktur", "correct": false, "because": "Außerhalb IT-Bereich"}, {"text": "Marketingkampagne starten", "correct": false, "because": "Anderer Bereich"}]');
